,"AstralGame","Profile");string arguments="--app=http://127.0.0.1:"+port+"/ --user-data-dir=\""+profile+"\" --no-first-run --disable-background-mode --window-size=1440,960";if(!fresh){Process.Start(edge,arguments);return;}var listener=new TcpListener(IPAddress.Loopback,port);listener.Start();var thread=new Thread(()=>{while(true){try{var client=listener.AcceptTcpClient();ThreadPool.QueueUserWorkItem(_=>Serve(client));}catch{return;}}});thread.IsBackground=true;thread.Start();var app=Process.Start(edge,arguments);app.WaitForExit();listener.Stop();}}catch(Exception e){MessageBox.Show("Astral could not start: "+e.Message,"Astral");}}static void Serve(TcpClient client){using(client){try{client.ReceiveTimeout=4000;client.SendTimeout=4000;var s=client.GetStream();var reader=new StreamReader(s,Encoding.ASCII,false,1024,true);var line=reader.ReadLine();if(line==null)return;var parts=line.Split(' ');if(parts.Length<2||parts[0]!="GET")return;var uri=new Uri("http://localhost"+parts[1]);string rel=Uri.UnescapeDataString(uri.AbsolutePath).TrimStart('/');if(rel=="")rel="index.html";string file=Path.GetFullPath(Path.Combine(root,rel.Replace('/',Path.DirectorySeparatorChar)));bool ok=file.StartsWith(root,StringComparison.OrdinalIgnoreCase)&&File.Exists(file);string ext=Path.GetExtension(file).ToLowerInvariant();string type=ext==".html"?"text/html; charset=utf-8":ext==".js"?"application/javascript":ext==".css"?"text/css":ext==".svg"?"image/svg+xml":ext==".png"?"image/png":ext==".ico"?"image/x-icon":"application/octet-stream";byte[] body=ok?File.ReadAllBytes(file):Encoding.UTF8.GetBytes("Not found");byte[] head=Encoding.ASCII.GetBytes("HTTP/1.1 "+(ok?"200 OK":"404 Not Found")+"\r\nContent-Type: "+type+"\r\nContent-Length: "+body.Length+"\r\nCache-Control: no-cache\r\nX-Content-Type-Options: nosniff\r\nConnection: close\r\n\r\n");s.Write(head,0,head.Length);s.Write(body,0,body.Length);}catch{}}}}